<?php
$esc = function($value) { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); };
$field = function($name, $fallback = '') use ($school) { $value = trim((string) ($school->$name ?? '')); return $value !== '' ? $value : $fallback; };
$profileAddress = implode(', ', array_filter(array_map('trim', array((string) ($school->sitio ?? ''), (string) ($school->brgy ?? ''), (string) ($school->city ?? ''), (string) ($school->province ?? '')))));
$administrator = trim(implode(' ', array_filter(array_map('trim', array((string) ($school->adminFName ?? ''), (string) ($school->adminMName ?? ''), (string) ($school->adminLName ?? ''))))));
$curriculum = $field('shs_tracks_offered', $field('educational_levels_offered', $field('course')));
$contact = implode(' / ', array_filter(array_map('trim', array((string) ($school->adminMobile ?? ''), (string) ($school->adminTel ?? '')))));
$firstSubmitted = trim((string) ($submission->first_submitted_at ?? ''));
?>
